[[nodiscard]] inline const WeaponPaintKitList* paintKitListFor(std::uint16_t defIndex)
{
    for (const auto& list : kWeaponPaintKitLists)
        if (list.defIndex == defIndex)
            return &list;
    return nullptr;
}

[[nodiscard]] inline const PaintKitEntry* paintKitFor(std::uint16_t defIndex, int kitId)
{
    const auto* list = paintKitListFor(defIndex);
    if (!list)
        return nullptr;
    for (std::uint16_t i = 0; i < list->kitCount; ++i) {
        const auto& kit = kPaintKits[list->kitIndices[i]];
        if (kit.id == kitId)
            return &kit;
    }
    return nullptr;
}

[[nodiscard]] inline const PaintKitEntry* paintKitById(int kitId)
{
    for (const auto& kit : kPaintKits)
        if (kit.id == kitId)
            return &kit;
    return nullptr;
}

